void dvb_usb_disconnect(struct usb_interface *intf)
{
    struct dvb_usb_device *d = usb_get_intfdata(intf);
    int i = intf->altsetting[0].desc.bInterfaceNumber;

    if (d && d->props.exit)
        d->props.exit(d);

    dvb_usbv2_exit();

    printk(KERN_INFO "DVB USB: interface %d disconnected\n", i);
}

void dvb_usb_disconnect(struct usb_interface *intf) {
    struct dvb_usb_device *d = usb_get_intfdata(intf);
    int i;

    for (i = 0; i < intf->num_altsetting; ++i)
        dev_info(&intf->dev, "Interface %d claimed by DVB USB driver\n", i);

    if (d->props.exit) {
        d->props.exit(d);
        d->props.exit = NULL;
    }

    dvb_usbv2_exit(d);
    dev_info(&intf->dev, "USB interface has been successfully disconnected\n");
}

void dvb_usb_disconnect(struct usb_interface *intf) {
    struct dvb_usb_device *d = usb_get_intfdata(intf);
    int num = intf->cur_altsetting->desc.bInterfaceNumber;

    if (d && d->props.exit)
        d->props.exit(d);

    dvb_usbv2_exit();

    printk(KERN_INFO "DVB/USB: Interface %d disconnected successfully.\n", num);
}

void dvb_usb_disconnect(struct usb_interface *intf)
{
    struct dvb_usb_device *d = usb_get_intfdata(intf);
    int i;

    if (!d)
        return;

    dev_info(&intf->dev, "DVB USB interface %d disconnected\n", intf->altsetting->desc.bInterfaceNumber);

    if (d->props.exit)
        d->props.exit(d);

    dvb_usbv2_exit(d);
}

void dvb_usb_disconnect(struct usb_interface *intf)
{
    struct dvb_usb_device *d = usb_get_intfdata(intf);
    int i;

    for (i = 0; i < intf->cur_altsetting->desc.bNumEndpoints; i++) {
        usb_disable_endpoint(intf, i);
    }

    if (d->props.exit)
        d->props.exit(d);

    dvb_usbv2_exit(d);
    printk(KERN_INFO "DVB USB: device has been disconnected\n");
}
